"""Fixed source temporal stylesheet templates; no production JS evaluator."""
import re

GANTT='\n  .mermaid-main-font {\n        font-family: ${options.fontFamily};\n  }\n\n  .exclude-range {\n    fill: ${options.excludeBkgColor};\n  }\n\n  .section {\n    stroke: none;\n    opacity: 0.2;\n  }\n\n  .section0 {\n    fill: ${options.sectionBkgColor};\n  }\n\n  .section2 {\n    fill: ${options.sectionBkgColor2};\n  }\n\n  .section1,\n  .section3 {\n    fill: ${options.altSectionBkgColor};\n    opacity: 0.2;\n  }\n\n  .sectionTitle0 {\n    fill: ${options.titleColor};\n  }\n\n  .sectionTitle1 {\n    fill: ${options.titleColor};\n  }\n\n  .sectionTitle2 {\n    fill: ${options.titleColor};\n  }\n\n  .sectionTitle3 {\n    fill: ${options.titleColor};\n  }\n\n  .sectionTitle {\n    text-anchor: start;\n    font-family: ${options.fontFamily};\n  }\n\n\n  /* Grid and axis */\n\n  .grid .tick {\n    stroke: ${options.gridColor};\n    opacity: 0.8;\n    shape-rendering: crispEdges;\n  }\n\n  .grid .tick text {\n    font-family: ${options.fontFamily};\n    fill: ${options.textColor};\n  }\n\n  .grid path {\n    stroke-width: 0;\n  }\n\n\n  /* Today line */\n\n  .today {\n    fill: none;\n    stroke: ${options.todayLineColor};\n    stroke-width: 2px;\n  }\n\n\n  /* Task styling */\n\n  /* Default task */\n\n  .task {\n    stroke-width: 2;\n  }\n\n  .taskText {\n    text-anchor: middle;\n    font-family: ${options.fontFamily};\n  }\n\n  .taskTextOutsideRight {\n    fill: ${options.taskTextDarkColor};\n    text-anchor: start;\n    font-family: ${options.fontFamily};\n  }\n\n  .taskTextOutsideLeft {\n    fill: ${options.taskTextDarkColor};\n    text-anchor: end;\n  }\n\n\n  /* Special case clickable */\n\n  .task.clickable {\n    cursor: pointer;\n  }\n\n  .taskText.clickable {\n    cursor: pointer;\n    fill: ${options.taskTextClickableColor} !important;\n    font-weight: bold;\n  }\n\n  .taskTextOutsideLeft.clickable {\n    cursor: pointer;\n    fill: ${options.taskTextClickableColor} !important;\n    font-weight: bold;\n  }\n\n  .taskTextOutsideRight.clickable {\n    cursor: pointer;\n    fill: ${options.taskTextClickableColor} !important;\n    font-weight: bold;\n  }\n\n\n  /* Specific task settings for the sections*/\n\n  .taskText0,\n  .taskText1,\n  .taskText2,\n  .taskText3 {\n    fill: ${options.taskTextColor};\n  }\n\n  .task0,\n  .task1,\n  .task2,\n  .task3 {\n    fill: ${options.taskBkgColor};\n    stroke: ${options.taskBorderColor};\n  }\n\n  .taskTextOutside0,\n  .taskTextOutside2\n  {\n    fill: ${options.taskTextOutsideColor};\n  }\n\n  .taskTextOutside1,\n  .taskTextOutside3 {\n    fill: ${options.taskTextOutsideColor};\n  }\n\n\n  /* Active task */\n\n  .active0,\n  .active1,\n  .active2,\n  .active3 {\n    fill: ${options.activeTaskBkgColor};\n    stroke: ${options.activeTaskBorderColor};\n  }\n\n  .activeText0,\n  .activeText1,\n  .activeText2,\n  .activeText3 {\n    fill: ${options.taskTextDarkColor} !important;\n  }\n\n\n  /* Completed task */\n\n  .done0,\n  .done1,\n  .done2,\n  .done3 {\n    stroke: ${options.doneTaskBorderColor};\n    fill: ${options.doneTaskBkgColor};\n    stroke-width: 2;\n  }\n\n  .doneText0,\n  .doneText1,\n  .doneText2,\n  .doneText3 {\n    fill: ${options.taskTextDarkColor} !important;\n  }\n\n  /* Done task text displayed outside the bar sits against the diagram background,\n     not against the done-task bar, so it must use the outside/contrast color. */\n  .doneText0.taskTextOutsideLeft,\n  .doneText0.taskTextOutsideRight,\n  .doneText1.taskTextOutsideLeft,\n  .doneText1.taskTextOutsideRight,\n  .doneText2.taskTextOutsideLeft,\n  .doneText2.taskTextOutsideRight,\n  .doneText3.taskTextOutsideLeft,\n  .doneText3.taskTextOutsideRight {\n    fill: ${options.taskTextOutsideColor} !important;\n  }\n\n\n  /* Tasks on the critical line */\n\n  .crit0,\n  .crit1,\n  .crit2,\n  .crit3 {\n    stroke: ${options.critBorderColor};\n    fill: ${options.critBkgColor};\n    stroke-width: 2;\n  }\n\n  .activeCrit0,\n  .activeCrit1,\n  .activeCrit2,\n  .activeCrit3 {\n    stroke: ${options.critBorderColor};\n    fill: ${options.activeTaskBkgColor};\n    stroke-width: 2;\n  }\n\n  .doneCrit0,\n  .doneCrit1,\n  .doneCrit2,\n  .doneCrit3 {\n    stroke: ${options.critBorderColor};\n    fill: ${options.doneTaskBkgColor};\n    stroke-width: 2;\n    cursor: pointer;\n    shape-rendering: crispEdges;\n  }\n\n  .milestone {\n    transform: rotate(45deg) scale(0.8,0.8);\n  }\n\n  .milestoneText {\n    font-style: italic;\n  }\n  .doneCritText0,\n  .doneCritText1,\n  .doneCritText2,\n  .doneCritText3 {\n    fill: ${options.taskTextDarkColor} !important;\n  }\n\n  /* Done-crit task text outside the bar — same reasoning as doneText above. */\n  .doneCritText0.taskTextOutsideLeft,\n  .doneCritText0.taskTextOutsideRight,\n  .doneCritText1.taskTextOutsideLeft,\n  .doneCritText1.taskTextOutsideRight,\n  .doneCritText2.taskTextOutsideLeft,\n  .doneCritText2.taskTextOutsideRight,\n  .doneCritText3.taskTextOutsideLeft,\n  .doneCritText3.taskTextOutsideRight {\n    fill: ${options.taskTextOutsideColor} !important;\n  }\n\n  .vert {\n    stroke: ${options.vertLineColor};\n  }\n\n  .vertText {\n    font-size: 15px;\n    text-anchor: middle;\n    fill: ${options.vertLineColor} !important;\n  }\n\n  .activeCritText0,\n  .activeCritText1,\n  .activeCritText2,\n  .activeCritText3 {\n    fill: ${options.taskTextDarkColor} !important;\n  }\n\n  .titleText {\n    text-anchor: middle;\n    font-size: 18px;\n    fill: ${options.titleColor || options.textColor};\n    font-family: ${options.fontFamily};\n  }\n'
JOURNEY=".label {\n    font-family: ${options.fontFamily};\n    color: ${options.textColor};\n  }\n  .mouth {\n    stroke: #666;\n  }\n\n  line {\n    stroke: ${options.textColor}\n  }\n\n  .legend {\n    fill: ${options.textColor};\n    font-family: ${options.fontFamily};\n  }\n\n  .label text {\n    fill: #333;\n  }\n  .label {\n    color: ${options.textColor}\n  }\n\n  .face {\n    ${options.faceColor ? `fill: ${options.faceColor}` : 'fill: #FFF8DC'};\n    stroke: #999;\n  }\n\n  .node rect,\n  .node circle,\n  .node ellipse,\n  .node polygon,\n  .node path {\n    fill: ${options.mainBkg};\n    stroke: ${options.nodeBorder};\n    stroke-width: 1px;\n  }\n\n  .node .label {\n    text-align: center;\n  }\n  .node.clickable {\n    cursor: pointer;\n  }\n\n  .arrowheadPath {\n    fill: ${options.arrowheadColor};\n  }\n\n  .edgePaths .path {\n    stroke: ${options.lineColor};\n    stroke-width: 1.5px;\n  }\n\n  .flowchart-link {\n    stroke: ${options.lineColor};\n    fill: none;\n  }\n\n  .edgeLabel {\n    background-color: ${options.edgeLabelBackground};\n    rect {\n      opacity: 0.5;\n    }\n    text-align: center;\n  }\n\n  .cluster rect {\n  }\n\n  .cluster text {\n    fill: ${options.titleColor};\n  }\n\n  div.mermaidTooltip {\n    position: absolute;\n    text-align: center;\n    max-width: 200px;\n    padding: 2px;\n    font-family: ${options.fontFamily};\n    font-size: 12px;\n    background: ${options.tertiaryColor};\n    border: 1px solid ${options.border2};\n    border-radius: 2px;\n    pointer-events: none;\n    z-index: 100;\n  }\n\n  .task-type-0, .section-type-0  {\n    ${options.fillType0 ? `fill: ${options.fillType0}` : ''};\n  }\n  .task-type-1, .section-type-1  {\n    ${options.fillType0 ? `fill: ${options.fillType1}` : ''};\n  }\n  .task-type-2, .section-type-2  {\n    ${options.fillType0 ? `fill: ${options.fillType2}` : ''};\n  }\n  .task-type-3, .section-type-3  {\n    ${options.fillType0 ? `fill: ${options.fillType3}` : ''};\n  }\n  .task-type-4, .section-type-4  {\n    ${options.fillType0 ? `fill: ${options.fillType4}` : ''};\n  }\n  .task-type-5, .section-type-5  {\n    ${options.fillType0 ? `fill: ${options.fillType5}` : ''};\n  }\n  .task-type-6, .section-type-6  {\n    ${options.fillType0 ? `fill: ${options.fillType6}` : ''};\n  }\n  .task-type-7, .section-type-7  {\n    ${options.fillType0 ? `fill: ${options.fillType7}` : ''};\n  }\n\n  .actor-0 {\n    ${options.actor0 ? `fill: ${options.actor0}` : ''};\n  }\n  .actor-1 {\n    ${options.actor1 ? `fill: ${options.actor1}` : ''};\n  }\n  .actor-2 {\n    ${options.actor2 ? `fill: ${options.actor2}` : ''};\n  }\n  .actor-3 {\n    ${options.actor3 ? `fill: ${options.actor3}` : ''};\n  }\n  .actor-4 {\n    ${options.actor4 ? `fill: ${options.actor4}` : ''};\n  }\n  .actor-5 {\n    ${options.actor5 ? `fill: ${options.actor5}` : ''};\n  }\n  ${getIconStyles()}\n"

def _value(options,key):
    value=options.get(key)
    if value is None:return 'undefined'
    if isinstance(value,bool):return str(value).lower()
    return str(value)

def gantt(options):
    def replace(match):
        expression=match[1]
        if expression=='options.titleColor || options.textColor':return _value(options,'titleColor') if options.get('titleColor') else _value(options,'textColor')
        if expression.startswith('options.') and expression[8:].isidentifier():return _value(options,expression[8:])
        raise ValueError('Unknown fixed Gantt style interpolation '+expression)
    css=re.sub(r'\$\{([^{}]+)\}',replace,GANTT)
    # The source milestone transform is already represented by the four
    # transformed polygon vertices. crispEdges is an SVG raster hint; native
    # Canvas keeps its normal antialiasing without changing logical geometry.
    return re.sub(r'(?:shape-rendering|transform)\s*:[^;{}]*;','',css)

def journey(options):
    text=JOURNEY
    text=text.replace('${getIconStyles()}','') # no icon SVG element is created by Journey
    # Fixed source uses SCSS nesting in this one block. Expand its exact
    # child selector before the shared flat-CSS provider, retaining the rule.
    text=text.replace('    rect {\n      opacity: 0.5;\n    }','')
    text+='\n.edgeLabel rect {opacity:0.5;}\n'
    for match in tuple(re.finditer(r"\$\{options\.(\w+) \? `([^`]*)` : '([^']*)'\}",text)):
        content=match[2] if options.get(match[1]) else match[3]
        content=re.sub(r'\$\{options\.(\w+)\}',lambda m:_value(options,m[1]),content)
        text=text.replace(match[0],content)
    css=re.sub(r'\$\{options\.(\w+)\}',lambda m:_value(options,m[1]),text)
    # Source's HTML tooltip is never created in the retained static scene.
    # Its position/z-index/pointer-events declarations belong to excluded
    # interaction, not to visible Journey task/actor/face paints.
    return re.sub(r'div\.mermaidTooltip\s*\{[^{}]*\}','',css)

def color_count(options):
    value=options.get('THEME_COLOR_LIMIT')
    return value if isinstance(value,int) and not isinstance(value,bool) and 0<value<=64 else 12

def timeline(options,theme,look,render_id):
    redux='redux' in theme;dark='dark' in theme;palette=theme in ('redux-color','redux-dark-color') and isinstance(options.get('borderColorArray'),(tuple,list)) and bool(options['borderColorArray']);rules=['.edge {stroke-width:3;fill:none;}'];limit=color_count(options)
    for i in range(limit):
        cls='.section-'+str(i-1);fill=_value(options,'cScale'+str(i));stroke='none'
        if redux:
            color=options['borderColorArray'][i%len(options['borderColorArray'])] if palette else _value(options,'mainBkg');fill=_value(options,'mainBkg') if dark and palette else color;stroke=color if palette else _value(options,'nodeBorder')
            shadow=('drop-shadow(rgba(255,255,255,.2) 4px 4px 0px)' if dark else 'drop-shadow(rgba(0,0,0,.06) 4px 4px 0px)') if look=='neo' else 'none'
            paint=f'fill:{fill};stroke:{stroke};stroke-width:{_value(options,"strokeWidth")};filter:{shadow};'
        else:paint=f'fill:{fill};'
        rules.append(f'{cls} rect,{cls} path,{cls} circle {{{paint}}}')
        rules.append(f'{cls} text {{fill:{_value(options,"nodeBorder") if redux else _value(options,"cScaleLabel"+str(i))};'+(f'font-weight:{_value(options,"fontWeight")};' if redux else '')+'}')
        rules.append(f'{cls} line {{stroke:{_value(options,"cScaleInv"+str(i))};stroke-width:3;}}')
        rules.append(f'.section-edge-{i-1} {{stroke:{_value(options,"cScale"+str(i))};}} .edge-depth-{i-1} {{stroke-width:{17-3*i};}}')
        rules.append('.lineWrapper line {stroke:'+_value(options,'nodeBorder' if redux else 'cScaleLabel'+str(i))+';'+('stroke-width:'+_value(options,'strokeWidth')+';' if redux else '')+'}')
        if look=='neo' and options.get('useGradient') and options.get('THEME_COLOR_LIMIT') and theme!='neutral':
            rules.append(f'{cls}[data-look="neo"] rect,{cls}[data-look="neo"] path,{cls}[data-look="neo"] circle {{fill:{_value(options,"mainBkg")};stroke:url(#{render_id}-gradient);stroke-width:2;}} {cls}[data-look="neo"] line {{stroke:url(#{render_id}-gradient);stroke-width:2;}}')
    rules.append('.section-root rect,.section-root path,.section-root circle {fill:'+_value(options,'git0')+';} .section-root text {fill:'+_value(options,'gitBranchLabel0')+';} .eventWrapper {filter:brightness(120%);}')
    return '\n'.join(rules)

def git(options,theme,render_id):
    redux=theme in ('redux','redux-dark','redux-color','redux-dark-color');neo=theme in ('neo','neo-dark');colored=theme in ('redux-color','redux-dark-color');generated=redux or neo;rules=[];borders=options.get('borderColorArray',())
    for i in range(color_count(options)):
        ci=i%8;node=_value(options,'nodeBorder');main=_value(options,'mainBkg')
        if not generated:color=_value(options,'git'+str(ci));highlight=_value(options,'gitInv'+str(ci));branch=_value(options,'gitBranchLabel'+str(ci));label=color
        elif neo and i>0:color=_value(options,'git'+str(ci));highlight=_value(options,'gitInv'+str(ci));branch=_value(options,'gitBranchLabel'+str(ci));label=main
        elif colored and i>0 and borders:color=borders[i%len(borders)];highlight=color;branch=node;label=main if 'dark' in theme else color
        else:color=node;highlight=node;branch=node;label=main
        rules.append(f'.branch-label{i} {{fill:{branch};'+(f'font-weight:{_value(options,"noteFontWeight")};' if redux else '')+'}')
        rules.append(f'.commit{i} {{stroke:{color};fill:{color};}} .commit-highlight{i} {{stroke:{highlight};fill:{main if colored and i==0 else highlight};}} .arrow{i} {{stroke:{color};}} .label{i} {{fill:{label};stroke:{color};stroke-width:{_value(options,"strokeWidth")};}}')
        if generated and options.get('useGradient') and render_id:rules.append(f'.label{i} {{fill:{main};stroke:url(#{render_id}-gradient);stroke-width:{_value(options,"strokeWidth")};}}')
    rules.extend((f'.branch {{stroke-width:{_value(options,"strokeWidth")};stroke:{_value(options,"commitLineColor") if options.get("commitLineColor") is not None else _value(options,"lineColor")};stroke-dasharray:'+('4 2' if generated else '2')+';}',f'.arrow {{stroke-width:{_value(options,"strokeWidth") if redux else 8};stroke-linecap:round;fill:none;}}',f'.commit-label {{font-size:{_value(options,"commitLabelFontSize")};fill:{_value(options,"nodeBorder" if generated else "commitLabelColor")};'+(f'font-weight:{_value(options,"noteFontWeight")};' if generated else '')+'}',f'.commit-label-bkg {{fill:{"transparent" if generated else _value(options,"commitLabelBackground")};'+('opacity:.5;' if not generated else '')+'}',f'.tag-label {{font-size:{_value(options,"tagLabelFontSize")};fill:{_value(options,"tagLabelColor")};}}',f'.tag-label-bkg {{fill:{_value(options,"mainBkg" if generated else "tagLabelBackground")};stroke:{_value(options,"nodeBorder" if generated else "tagLabelBorder")};'+(f'filter:{_value(options,"dropShadow")};' if generated else '')+'}',f'.tag-hole {{fill:{_value(options,"textColor")};}}',f'.commit-merge,.commit-reverse,.commit-highlight-inner {{stroke:{_value(options,"mainBkg" if generated else "primaryColor")};fill:{_value(options,"mainBkg" if generated else "primaryColor")};}}',f'.commit-reverse {{stroke-width:{_value(options,"strokeWidth") if generated else 3};}}',(f'.commit-bullets {{fill:{_value(options,"nodeBorder")};}}' if generated else ''),f'.gitTitleText {{text-anchor:middle;font-size:18px;fill:{_value(options,"textColor")};}}'))
    rules.insert(0,'.commit-id,.commit-msg,.branch-label {fill:lightgrey;color:lightgrey;font-family:'+_value(options,'fontFamily')+';}')
    return '\n'.join(rules)
